void gdImageSetClip (gdImagePtr im, int x1, int y1, int x2, int y2)
{
  if (x1 < 0) {
    x1 = 0;
  }
  if (x1 >= im->sx) {
    x1 = im->sx - 1;
  }
  if (x2 < 0) {
    x2 = 0;
  }
  if (x2 >= im->sx) {
    x2 = im->sx - 1;
  }
  if (y1 < 0) {
    y1 = 0;
  }
  if (y1 >= im->sy) {
    y1 = im->sy - 1;
  }
  if (y2 < 0) {
    y2 = 0;
  }
  if (y2 >= im->sy) {
    y2 = im->sy - 1;
  }
  im->cx1 = x1;
  im->cy1 = y1;
  im->cx2 = x2;
  im->cy2 = y2;
}

static bool send_status(Transport *transport, Writer::Format format,
                        const char *mime) {
  transport->replaceHeader("Content-Type", mime);
  transport->sendString(ServerStats::ReportStatus(format));
  return true;
}

bool AdminRequestHandler::handleVMRequest(const std::string &cmd,
                                          Transport *transport) {
  if (cmd == "vm-tcspace") {
    transport->sendString(jit::tc::getTCSpace());
    return true;
  }
  if (cmd == "vm-tcaddr") {
    transport->sendString(jit::tc::getTCAddrs());
    return true;
  }
  if (cmd == "vm-namedentities") {
    std::ostringstream result;
    result << NamedEntity::tableSize();
    transport->sendString(result.str());
    return true;
  }
  if (cmd == "vm-dump-tc") {
    if (jit::tc::dump()) {
      transport->sendString("Done");
    } else {
      transport->sendString("Error dumping the translation cache");
    }
    return true;
  }
  return false;
}

void AdminRequestHandler::handleProxyRequest(const std::string& /*cmd*/,
                                             Transport* transport) {
  try {
    auto const percentStr = transport->getParam("percentage");
    auto const percent    = percentStr.empty() ? 0 : folly::to<int>(percentStr);
    if (percent < 0 || percent > 100) {
      throw std::range_error("must be in [0, 100]");
    }

    setProxyOriginPercentage(transport->getParam("origin"), percent);
    transport->sendString("Origin and percentage updated");
  } catch (const std::range_error& re) {
    transport->sendString(folly::sformat("Invalid percentage: {}", re.what()));
  }
}

return runLight("popen", [&] (LightProcess* proc) -> FILE* {
      auto afdt_fd = proc->m_afdt_fd;
      lwp_write(afdt_fd, "popen", type, cmd, cwd ? cwd : "");

      std::string buf;
      lwp_read(afdt_fd, buf);
      if (buf == "error") {
        return nullptr;
      }

      pid_t pid;
      lwp_read(afdt_fd, pid);
      assert(pid);
      int fd = recv_fd(afdt_fd);
      if (fd < 0) {
        Logger::Error("Light process failed to send the file descriptor.");
        return nullptr;
      }
      FILE *f = fdopen(fd, type);
      if (f) {
        proc->m_popenMap[f] = pid;
      }
      return f;
    }, static_cast<FILE*>(nullptr));

return runLight("execve", [&] (LightProcess* proc) -> pid_t {
      auto fin = proc->m_afdt_fd;
      auto fout = proc->m_afdt_fd;

      lwp_write(fout, "execve", path, cwd, argv, envp, options, pgid, (size_t) fds.size());
      for (const auto& [target_fd, current_fd]: fds) {
        lwp_write(fout, target_fd);
        send_fd(fout, current_fd);
      }

      std::string buf;
      lwp_read(fin, buf);
      if (buf == "success") {
        pid_t pid;
        lwp_read(fin, pid);
        return pid;
      }
      assert(buf == "error");

      int ret;
      int saved_errno;
      lwp_read(fin, ret, saved_errno);
      errno = saved_errno;
      return (pid_t) ret;
  }, static_cast<pid_t>(-1));

return runLight("waitpid", [&] (LightProcess* proc) -> pid_t {
      lwp_write(proc->m_afdt_fd, "waitpid", pid, options, timeout);

      pid_t ret;
